import Foundation
import SwiftData

/// A small example module so new users can try studying straight away.
/// Its cards are generated by the same parsers used for imported files.
enum SampleData {
    static let cellStructureMarkdown = """
    # Cell Structure

    ## What is a cell?
    The smallest **structural and functional unit** of a living organism.

    ## Mitochondria
    - Produce energy (ATP) through cellular respiration
    - Have their own DNA

    ## Key Terms
    - **Nucleus**: Holds the cell's genetic material (DNA).
    - **Ribosome**: Builds proteins from amino acids.
    - **Cell membrane**: Controls what enters and leaves the cell.

    Q: Which organelle carries out photosynthesis?
    A: The *chloroplast*, found in plant cells.
    """

    static let vocabularyCSV = """
    term,definition
    Osmosis,"Movement of water across a semi-permeable membrane, from low to high solute concentration"
    Diffusion,Movement of particles from an area of high concentration to an area of low concentration
    Enzyme,A protein that speeds up a chemical reaction without being used up
    Homeostasis,Keeping a stable internal environment
    """

    static func insertSampleModule(into context: ModelContext) {
        let module = StudyModule(
            name: "Biology (Sample)",
            details: "An example module. Delete it whenever you like.",
            colorName: ModuleColor.green.rawValue
        )
        context.insert(module)

        let chapters: [(name: String, fileName: String, kind: SourceKind, cards: [ParsedCard])] = [
            ("Cell Structure", "cell-structure.md", .markdown, MarkdownParser.parse(cellStructureMarkdown).cards),
            ("Key Vocabulary", "vocabulary.csv", .csv, CSVParser.parse(vocabularyCSV).cards),
        ]
        for (index, entry) in chapters.enumerated() {
            let chapter = Chapter(name: entry.name, sortIndex: index)
            context.insert(chapter)
            chapter.module = module
            CardStore.addCards(entry.cards, to: chapter, fileName: entry.fileName, kind: entry.kind, in: context)
        }
        CardStore.save(context)
    }
}
